INSERT INTO product (id, category_id, seller_id, price, discount, name, description, available_count)
SELECT products.id, c.id, s.user_id, products.price, products.discount,
       products.name, products.description, products.available_count
FROM (VALUES
    (1, 'Аксессуары', 'seed.applevibe@example.test', 5999.99, 10, 'Рюкзак Sigma-Back', 'Городской рюкзак Sigma-Back объёмом 16 литров подходит для учёбы, прогулок и коротких поездок. Основное отделение широко раскрывается, поэтому внутри удобно разместить книги, сменную одежду и повседневные вещи. В переднем кармане на молнии можно хранить ключи и другие мелочи, а боковые карманы пригодятся для небольших предметов. Съёмная вставка в спинке служит сидушкой во время отдыха на природе. Верхние ручки позволяют нести рюкзак в руке, когда его неудобно надевать на плечи.', 12),
    (2, 'Техника', 'seed.nokiavibe@example.test', 2499.99, 5, 'Камера Sony PXW-Z90', 'Профессиональная видеокамера Sony PXW-Z90 предназначена для репортажей, интервью и съёмки мероприятий. Дюймовый многослойный сенсор Exmor RS позволяет записывать детализированное видео в разрешении 4K. Объектив ZEISS с двенадцатикратным оптическим зумом помогает снимать как общие планы, так и удалённые объекты. Фазовая автофокусировка упрощает сопровождение движущегося человека в кадре. Входы XLR позволяют подключить профессиональные микрофоны для записи речи и окружающих звуков.', 8),
    (3, 'Техника', 'seed.samsungvibe@example.test', 1149.99, 15, 'Наушники Samsung Galaxy Buds2', 'Беспроводные внутриканальные наушники Samsung Galaxy Buds2 подходят для музыки, подкастов и телефонных разговоров. Активное шумоподавление помогает сосредоточиться на звуке в транспорте или оживлённом офисе. Режим звукового фона позволяет слышать происходящее вокруг, не вынимая наушники. Силиконовые насадки разных размеров помогают подобрать удобную посадку. Компактный зарядный футляр удобно носить в кармане и использовать для подзарядки в течение дня.', 20),
    (4, 'Техника', 'seed.laptopvibe@example.test', 2999.99, 0, 'Клавиатура Logitech K380', 'Компактная беспроводная клавиатура Logitech K380 освобождает место на столе и подходит для работы в дороге. Соединение по Bluetooth позволяет использовать её с совместимыми компьютерами, планшетами и смартфонами. Функция Easy-Switch помогает переключаться между тремя подключёнными устройствами отдельными клавишами. Низкопрофильные круглые клавиши обеспечивают спокойный и комфортный набор текста. Питание от двух батареек AAA избавляет от необходимости постоянно подключать зарядный кабель.', 25),
    (5, 'Товары для дома', 'seed.techvibe@example.test', 649.99, 5, 'Настольная лампа IKEA TERTIAL', 'Настольная лампа IKEA TERTIAL подходит для рабочего стола, домашней мастерской и уголка для чтения. Регулируемый металлический кронштейн позволяет менять высоту и положение источника света. Поворотный плафон помогает направить свет на книгу, записи или небольшие детали. Крепление к краю столешницы оставляет больше свободного места на рабочей поверхности. Стандартный цоколь E27 позволяет самостоятельно выбрать совместимую лампочку с подходящей яркостью и цветовой температурой.', 10),
    (6, 'Техника', 'seed.laptopvibe@example.test', 1299.99, 10, 'Ноутбук Apple MacBook Air 13 M1', 'Apple MacBook Air с чипом M1 — лёгкий ноутбук с экраном Retina диагональю 13,3 дюйма для работы, учёбы и повседневных задач. Безвентиляторная конструкция обеспечивает бесшумную работу даже в тихой комнате. Клавиатура Magic Keyboard удобна для набора больших текстов, а большой трекпад поддерживает управление жестами. Датчик Touch ID позволяет разблокировать компьютер и подтверждать действия отпечатком пальца. Два порта Thunderbolt с разъёмом USB-C используются для зарядки и подключения совместимой периферии.', 6),
    (7, 'Техника', 'seed.samsungvibe@example.test', 699.99, 20, 'Смартфон Samsung Galaxy S23', 'Samsung Galaxy S23 — компактный флагманский смартфон с экраном Dynamic AMOLED 2X диагональю 6,1 дюйма. Частота обновления до 120 Гц делает прокрутку страниц и интерфейс плавными. Основная камера на 50 Мп дополнена сверхширокоугольной камерой и телефотокамерой с трёхкратным оптическим зумом. Процессор Snapdragon 8 Gen 2 for Galaxy подходит для многозадачности, мобильных игр и обработки фотографий. Корпус с защитой IP68 рассчитан на повышенную устойчивость к пыли и воде в пределах условий производителя.', 14),
    (8, 'Техника', 'seed.nokiavibe@example.test', 199.99, 0, 'Умные часы Apple Watch Series 9', 'Умные часы Apple Watch Series 9 помогают следить за повседневной активностью и получать уведомления с iPhone. Постоянно включённый дисплей позволяет быстро посмотреть время и показатели тренировки без дополнительного касания. Приложение тренировок поддерживает разные виды активности, включая ходьбу, бег, плавание и велопоездки. Часы отслеживают пульс и помогают наблюдать за продолжительностью сна. Для первоначальной настройки и полноценной работы необходим совместимый iPhone.', 18),
    (9, 'Техника', 'seed.applevibe@example.test', 89.99, 5, 'Портативная колонка JBL Flip 6', 'Портативная Bluetooth-колонка JBL Flip 6 подходит для прослушивания музыки дома, на прогулке и в поездках. Двухполосная акустическая система сочетает отдельный высокочастотный динамик с динамиком для средних и низких частот. Защита IP67 помогает корпусу противостоять пыли и случайному контакту с водой. Встроенный аккумулятор обеспечивает до 12 часов воспроизведения, при этом фактическое время зависит от громкости и характера музыки. Функция PartyBoost позволяет объединять совместимые колонки JBL для совместного воспроизведения.', 16)
) AS products(id, category, seller_email, price, discount, name, description, available_count)
JOIN category AS c ON c.category = products.category
JOIN "user" AS u ON u.email = products.seller_email
JOIN seller AS s ON s.user_id = u.id;

SELECT setval(pg_get_serial_sequence('product', 'id'), MAX(id), true)
FROM product;

